#include <stdio.h>

#define mod 1000000007
long long dp[55][55][205]={};
long long c[55][55]={};
int n,lim,A=0,B=0,i,j,k,ii,jj;
int min(int a,int b){return a<b?a:b;}
int max(int a,int b){return a<b?b:a;}
int main(){
	scanf("%d %d",&n,&lim);
	for(i=0;i<n;i++){
		int fk; scanf("%d",&fk);
		if(fk==50) A++;
		else B++;
	}
	dp[A][B][0]=1;
	c[0][0]=1;
	for(i=1;i<=50;i++){
		for(j=0;j<=i;j++){
			c[i][j]=c[i-1][j-1]+c[i-1][j];
		}
	}
	for(k=1;k<=4*n;k++){
		for(i=A;i>=0;i--){
			for(j=B;j>=0;j--){
				int s=k%2;
				dp[i][j][k]=0;
				if(s){
					for(ii=i;ii<=A;ii++){
						int f=lim-(ii-i)*50;
						if(f>=0){
							f/=100;
							f+=j; f=min(f,B);
							for(jj=j;jj<=f;jj++){
								if((i!=ii || j!=jj)){
									dp[i][j][k]+=(dp[ii][jj][k-1]*c[ii][ii-i]*c[jj][jj-j])%mod;
									dp[i][j][k]%=mod;
								}
							}
						}
					}
				}else{
					for(ii=0;ii<=i;ii++){
						int f=lim-(i-ii)*50;
						if(f>=0){
							f/=100; f=max(j-f,0);
							for(jj=f;jj<=j;jj++){
								if((i!=ii || j!=jj)){
									dp[i][j][k]+=(dp[ii][jj][k-1]*c[A-ii][i-ii]*c[B-jj][j-jj])%mod;
									dp[i][j][k]%=mod;
								}
							}
						}
					}
				}
				if(dp[0][0][k]){
					printf("%d\n",k);
					printf("%lld\n",dp[0][0][k]);
					return 0;
				}
			}
		}
	}
	puts("-1\n0");
}
